<?php
require_once __DIR__.'/includes/layout.php';
require_once __DIR__.'/includes/import_csv.php';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='import_csv') importer('nhat','nhat.php');
require_role(['SO']);
if($_SERVER['REQUEST_METHOD']==='POST')task('nhat.php',function(PDO $db,array $u){if($u['vai_tro']!=='SO')throw new RuntimeException('Chỉ Sở GD&ĐT phê duyệt kết quả.');$id=filter_var(val('id'),FILTER_VALIDATE_INT);if(!$id)throw new RuntimeException('Thiếu mã kết quả.');$db->beginTransaction();try{$q=$db->prepare('SELECT * FROM ket_qua_xet_tuyen WHERE id=? FOR UPDATE');$q->execute([$id]);$kq=$q->fetch();if(!$kq||$kq['trang_thai']!=='DU_KIEN')throw new RuntimeException('Chỉ được duyệt kết quả đang dự kiến.');$q=$db->prepare('SELECT COUNT(*) FROM diem_thi d JOIN bai_thi b ON d.ma_bai=b.ma_bai WHERE b.ma_thi_sinh=? AND d.trang_thai<>?');$q->execute([$kq['ma_thi_sinh'],'DA_CHOT']);if((int)$q->fetchColumn()>0)throw new RuntimeException('Còn điểm thi chưa được chốt.');$q=$db->prepare('SELECT COUNT(*) FROM nguyen_vong WHERE ma_thi_sinh=? AND da_xac_nhan=1');$q->execute([$kq['ma_thi_sinh']]);if((int)$q->fetchColumn()===0)throw new RuntimeException('Thiếu nguyện vọng được xác nhận.');if($kq['ket_qua']==='TRUNG_TUYEN'){
 if(!$kq['ma_truong']||!$kq['nguyen_vong_trung_tuyen'])throw new RuntimeException('Thiếu trường hoặc thứ tự nguyện vọng trúng tuyển.');$q=$db->prepare('SELECT COUNT(*) FROM nguyen_vong WHERE ma_thi_sinh=? AND ma_truong=? AND thu_tu=? AND da_xac_nhan=1');$q->execute([$kq['ma_thi_sinh'],$kq['ma_truong'],$kq['nguyen_vong_trung_tuyen']]);if(!$q->fetchColumn())throw new RuntimeException('Trường trúng tuyển không khớp nguyện vọng được xác nhận.');$q=$db->prepare("SELECT COALESCE(SUM(so_luong),0) FROM chi_tieu WHERE ma_ky_thi=? AND ma_truong=? AND trang_thai='DA_DUYET'");$q->execute([$kq['ma_ky_thi'],$kq['ma_truong']]);$quota=(int)$q->fetchColumn();if(!$quota)throw new RuntimeException('Trường chưa có chỉ tiêu được duyệt.');$q=$db->prepare("SELECT COUNT(*) FROM ket_qua_xet_tuyen WHERE ma_ky_thi=? AND ma_truong=? AND ket_qua='TRUNG_TUYEN' AND trang_thai='DA_DUYET'");$q->execute([$kq['ma_ky_thi'],$kq['ma_truong']]);if((int)$q->fetchColumn()>=$quota)throw new RuntimeException('Đã hết chỉ tiêu phê duyệt.');}
 $q=$db->prepare("UPDATE ket_qua_xet_tuyen SET trang_thai='DA_DUYET',nguoi_duyet=?,ngay_duyet=NOW() WHERE id=? AND trang_thai='DU_KIEN'");$q->execute([$u['id'],$id]);audit($db,$u['id'],'PHE_DUYET_KET_QUA','Kết quả #'.$id);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}});
page_start('Phê duyệt kết quả tuyển sinh','nhat');echo '<div class="note">QT10: Kết quả xét tuyển NV1 → NV2 → NV3 phải được <b>tính thành danh sách Dự kiến trước</b>. Trang này chỉ phê duyệt từng kết quả đã có, kiểm tra trạng thái điểm, nguyện vọng và chỉ tiêu. Không tự tính/xếp hạng vì báo cáo chưa cung cấp đầy đủ công thức & quy tắc đồng điểm.</div><div class="panel"><h2>Phê duyệt kết quả dự kiến</h2>';form_open();echo '<input type="hidden" name="action" value="approve">';select_field('id','Kết quả dự kiến',"SELECT id,CONCAT(ma_thi_sinh,' · ',ket_qua) AS label FROM ket_qua_xet_tuyen WHERE trang_thai='DU_KIEN' ORDER BY id",'id','label');form_close('Phê duyệt kết quả đã chọn');echo '</div><div class="panel"><h2>Danh sách kết quả</h2>';table_rows(db()->query('SELECT k.id,t.ho_ten,k.tong_diem,k.nguyen_vong_trung_tuyen,k.ma_truong,k.ket_qua,k.trang_thai FROM ket_qua_xet_tuyen k JOIN thi_sinh t ON k.ma_thi_sinh=t.ma_thi_sinh ORDER BY k.id DESC')->fetchAll(),['Mã','Thí sinh','Tổng điểm','NV','Trường','Kết quả','Trạng thái']);echo '</div>';import_panel('nhat','Kết quả xét tuyển dự kiến');page_end();
